class Solution {
public:
    string getPermutation(int n, int k) {
        vector<int> pool;
        int block = 1;
        for (int d = 1; d <= n; d++) {
            pool.push_back(d);
            block *= d;
        }
        k--;
        string res;
        for (int left = n; left > 0; left--) {
            block /= left;
            int idx = k / block;
            k %= block;
            res += to_string(pool[idx]);
            pool.erase(pool.begin() + idx);
        }
        return res;
    }
};
